import React, { useEffect, useState } from "react";

function Home({
  token,
  email,
  onLogout,
  onShowDeposit,
  onShowWithdraw,
  onShowAdminWithdraw,
  onShowAdminDepositRequests,
  onShowHistory,
  onShowAdminUserHistory,
}) {
  const [balance, setBalance] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    if (!token) return;

    const fetchUserData = async () => {
      try {
        const res = await fetch("http://localhost:8080/api/user/profile", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error("Failed to fetch user profile");
        const data = await res.json();
        setIsAdmin(data.role?.toLowerCase() === "admin");
      } catch (err) {
        console.error("Failed to get user role:", err);
      }
    };

    fetchUserData();
  }, [token]);

  useEffect(() => {
    if (!token) return;

    const fetchBalance = async () => {
      try {
        const res = await fetch("http://localhost:8080/api/user/balance", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json();
        if (res.ok && data.balance != null && !isNaN(data.balance)) {
          setBalance(parseFloat(data.balance));
        } else {
          throw new Error("Invalid balance response");
        }
      } catch (error) {
        console.error("Failed to fetch balance:", error);
        setBalance("Error");
      } finally {
        setLoading(false);
      }
    };

    fetchBalance();
  }, [token]);

  const renderBalance = () => {
    if (loading) return "লোড হচ্ছে...";
    if (balance === "Error") return "ব্যালেন্স লোড হয়নি";
    return `৳ ${balance.toFixed(2)}`;
  };

  return (
    <div style={styles.page}>
      <header style={styles.header}>
        <div style={styles.logo}>🎮 Ludo Dashboard</div>
        <div style={styles.userInfo}>
          <span>{email}</span>
          <span style={styles.balance}>{renderBalance()}</span>
          <button style={styles.logoutButton} onClick={onLogout}>🚪 লগআউট</button>
        </div>
      </header>

      <main style={styles.main}>
        <div style={styles.card}>
          <h1 style={styles.title}>হোম পেজে স্বাগতম</h1>
          <p style={styles.subtitle}>আপনি সফলভাবে লগইন করেছেন। নিচে আপনার অপশনগুলো দেখুন।</p>

          <div style={styles.buttonGroup}>
            <ActionButton text="💰 ডিপোজিট" onClick={onShowDeposit} />
            <ActionButton text="💸 উইথড্র" onClick={onShowWithdraw} color="#dc3545" />
            <ActionButton text="📥 অ্যাডমিন ডিপোজিট রিকোয়েস্ট" onClick={onShowAdminDepositRequests} color="#6f42c1" />
            {isAdmin && (
              <>
                <ActionButton text="📤 অ্যাডমিন উইথড্র রিকোয়েস্ট" onClick={onShowAdminWithdraw} color="#007bff" />
                <ActionButton text="🧾 ইউজার হিস্টোরি" onClick={onShowAdminUserHistory} color="#6c757d" />
              </>
            )}
            <ActionButton text="📂 আমার হিস্টোরি" onClick={onShowHistory} color="#17a2b8" />
          </div>
        </div>
      </main>
    </div>
  );
}

function ActionButton({ text, onClick, color = "#28a745" }) {
  return (
    <button
      onClick={onClick}
      style={{
        ...styles.actionButton,
        backgroundColor: color
      }}
    >
      {text}
    </button>
  );
}

const styles = {
  page: {
    fontFamily: "'Segoe UI', sans-serif",
    backgroundColor: "#eef1f5",
    minHeight: "100vh",
    margin: 0,
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "15px 30px",
    backgroundColor: "#343a40",
    color: "#fff",
  },
  logo: {
    fontSize: "20px",
    fontWeight: "bold",
  },
  userInfo: {
    display: "flex",
    alignItems: "center",
    gap: "15px",
  },
  balance: {
    fontSize: "16px",
    backgroundColor: "#17a2b8",
    padding: "6px 12px",
    borderRadius: "6px",
    color: "white",
    fontWeight: "bold",
  },
  logoutButton: {
    padding: "8px 16px",
    backgroundColor: "#dc3545",
    color: "white",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
  },
  main: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    padding: "40px 20px",
  },
  card: {
    backgroundColor: "#fff",
    padding: "30px 40px",
    borderRadius: "12px",
    boxShadow: "0 8px 16px rgba(0,0,0,0.1)",
    maxWidth: "700px",
    width: "100%",
    textAlign: "center",
  },
  title: {
    marginBottom: "10px",
    fontSize: "26px",
    color: "#333",
  },
  subtitle: {
    color: "#555",
    marginBottom: "25px",
  },
  buttonGroup: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))",
    gap: "15px",
  },
  actionButton: {
    padding: "14px 20px",
    fontSize: "16px",
    borderRadius: "6px",
    border: "none",
    color: "#fff",
    fontWeight: "bold",
    cursor: "pointer",
    transition: "all 0.2s ease-in-out",
  },
};

export default Home;
